import {raw} from 'white-label-view/jsx-runtime';

interface PageData {
    cdn: string;
    meta: {description: string};
    siteUrl: string;
    structuredData: unknown;
    title: string;
    version: string;
}

const sources = [
    ['source-1', 'Library of Congress: The California Gold Rush', 'https://www.loc.gov/classroom-materials/immigration/rise-of-industrial-america-1876-1900/california-gold-rush/'],
    ['source-2', 'National Park Service: California Gold Rush', 'https://www.nps.gov/cali/learn/historyculture/california-gold-rush.htm'],
    ['source-3', 'State of Alaska: Gold Panning in Alaska', 'https://www.alaska.gov/kids/learn/goldpanning.htm'],
    ['source-4', 'U.S. Forest Service: Juneau Mining History', 'https://www.fs.usda.gov/r10/tongass/forest-facts/resources/history/juneau-mining.shtml'],
    ['source-5', 'National Park Service: What Was the Klondike Gold Rush?', 'https://www.nps.gov/klgo/learn/goldrush.htm'],
    ['source-6', 'National Park Service: Skagway, Gateway to the Klondike', 'https://www.nps.gov/articles/skagway-gateway-to-the-klondike-teaching-with-historic-places.htm'],
    ['source-7', 'National Park Service: A Ton of Goods', 'https://www.nps.gov/klgo/learn/historyculture/tonofgoods.htm'],
    ['source-8', 'National Park Service: Cape Nome Mining District Discovery Sites', 'https://www.nps.gov/places/cape-nome-mining-district-discovery-sites.htm'],
    ['source-9', 'State of Alaska: Alaska Chronology', 'https://alaska.gov/kids/learn/chronology.htm'],
    ['source-10', 'Alaska DOT: Historic Roads of Alaska', 'https://dot.alaska.gov/stwddes/desenviron/assets/pdf/historic/Book_Historic_Roads_2017.pdf'],
    ['source-11', 'Alaska Department of Labor: Alaska’s Mining Industry', 'https://live.laborstats.alaska.gov/sites/default/files/trendsArt/oct10art1.pdf']
] as const;

export default function IndexPage(data: Record<string, unknown>) {
    const page = data as unknown as PageData;
    const structuredData = JSON.stringify(page.structuredData).replaceAll('<', '\\u003c');

    return (
        <html id="index" lang="en-US" dir="ltr">
            <head>
                <meta charset="utf-8" />
                <meta name="viewport" content="width=device-width, initial-scale=1" />
                <title>{page.title}</title>
                <meta name="description" content={page.meta.description} />
                <meta name="robots" content="index,follow,max-image-preview:large,max-snippet:-1,max-video-preview:-1" />
                <link rel="canonical" href={`${page.siteUrl}/`} />
                <meta property="og:title" content={page.title} />
                <meta property="og:description" content={page.meta.description} />
                <meta property="og:type" content="article" />
                <meta property="og:url" content={`${page.siteUrl}/`} />
                <link rel="stylesheet" href={`${page.cdn}release/${page.version}/assets/style/global.css`} media="all" />
                <link rel="stylesheet" href={`${page.cdn}release/${page.version}/assets/style/print.css`} media="print" />
                <script type="application/ld+json">{raw(structuredData)}</script>
            </head>
            <body itemscope itemtype="https://schema.org/Article">
                <a className="skip-link" href="#main">Skip to the history</a>
                <div className="reading-progress" aria-hidden="true"><span data-reading-progress /></div>
                <header className="site-header">
                    <div className="container site-header__inner">
                        <a className="wordmark" href="#top" aria-label="Gold North, home">Gold North</a>
                        <nav aria-label="Primary navigation">
                            <a href="#american-rush">American rush</a>
                            <a href="#alaska">Alaska</a>
                            <a href="#consequences">Consequences</a>
                            <a href="#sources">Sources</a>
                        </nav>
                    </div>
                </header>
                <main id="main" tabindex="-1">
                    <section className="hero" id="top">
                        <div className="container hero__grid">
                            <div>
                                <p className="eyebrow">1848–1906 · California to the Arctic</p>
                                <h1>Gold changed the American map. Alaska changed the journey.</h1>
                                <p className="hero__lede">A concise, sourced history of the rushes that pulled hundreds of thousands west—and of the ports, trails, Native homelands, mining camps, and permanent cities they reshaped in Alaska.</p>
                                <a className="button-primary" href="#american-rush">Follow the movement north</a>
                            </div>
                            <aside className="hero__fact" aria-label="At a glance">
                                <span className="hero__number">58 years</span>
                                <p>separate the discovery at Sutter’s Mill from Alaska’s 1906 production peak.</p>
                                <div className="route" aria-hidden="true"><span>California</span><i></i><span>Juneau</span><i></i><span>Klondike</span><i></i><span>Nome</span><i></i><span>Fairbanks</span></div>
                            </aside>
                        </div>
                    </section>

                    <section className="section" id="american-rush">
                        <div className="container article-grid">
                            <div className="section-label">01 · The pattern</div>
                            <article>
                                <p className="eyebrow">California, 1848</p>
                                <h2>A discovery becomes a national migration</h2>
                                <p className="standfirst">James Marshall found gold at John Sutter’s sawmill on January 24, 1848. News moved faster than reliable information. By 1849, migrants were crossing the continent and sailing around Cape Horn or through Panama, chasing a chance that few could calculate.</p>
                                <p>The California rush established a pattern repeated across the West: a discovery, a publicity wave, mass movement, instant settlements, improvised claim rules, then consolidation as surface deposits declined. Merchants, transport operators, and landowners often found steadier returns than individual prospectors. Mining also accelerated dispossession, violence, environmental damage, and discriminatory laws—costs that celebratory “strike it rich” stories routinely obscure.</p>
                                <p>Subsequent strikes carried the mining frontier through the interior West and toward the North Pacific. Alaska was not simply the final stop in one continuous rush. It experienced several overlapping rushes, each with a different geography: hard-rock mining near Juneau, transit through Southeast Alaska to Canada’s Klondike, beach deposits at Nome, and river-valley placers around Fairbanks.</p>
                                <p className="source-note">See sources <a href="#source-1">1</a> and <a href="#source-2">2</a>.</p>
                            </article>
                        </div>
                    </section>

                    <section className="section section--dark" id="alaska">
                        <div className="container">
                            <div className="section-heading">
                                <div><span className="section-label">02 · Alaska</span><h2>Four northern gold-rush stories</h2></div>
                                <p>Choose an era to focus the chronology. All content remains available without JavaScript.</p>
                            </div>
                            <nav className="era-controls" aria-label="Filter the Alaska timeline">
                                <a href="/?era=all#alaska" data-era-filter="all" data-pushstate aria-current="page">All eras</a>
                                <a href="/?era=southeast#alaska" data-era-filter="southeast" data-pushstate>Southeast</a>
                                <a href="/?era=gateway#alaska" data-era-filter="gateway" data-pushstate>Klondike gateway</a>
                                <a href="/?era=far-north#alaska" data-era-filter="far-north" data-pushstate>Nome &amp; Interior</a>
                            </nav>
                            <div className="visually-hidden" aria-live="polite" aria-atomic="true" data-filter-status><p>Showing all four eras.</p></div>
                            <div className="timeline" data-era-list>
                                <article className="timeline-card" data-era="southeast">
                                    <div className="timeline-card__date">1880</div>
                                    <div><p className="eyebrow">Gold Creek · Lingít Aaní</p><h3>Juneau: a mining town takes root</h3><p>Richard Harris and Joe Juneau, guided by Tlingit leader Kowee, located gold in the Silver Bow Basin. A camp formed near present-day Juneau. Placer work gave way to capital-intensive hard-rock operations around the Gastineau Channel, including the Treadwell complex on Douglas Island.</p><p>The familiar founding story can hide an essential fact: this was and remains Tlingit homeland. Tlingit knowledge, trade routes, labor, and diplomacy made movement through Southeast Alaska possible, while settlement and industrial mining transformed access to land and resources.</p><p className="source-note">Sources <a href="#source-3">3</a> and <a href="#source-4">4</a>.</p></div>
                                </article>
                                <article className="timeline-card" data-era="gateway">
                                    <div className="timeline-card__date">1896–99</div>
                                    <div><p className="eyebrow">Skagway &amp; Dyea · The Klondike gateway</p><h3>The strike was Canadian. The bottleneck was Alaskan.</h3><p>Gold discovered on Bonanza Creek in the Yukon in August 1896 triggered a stampede after successful miners reached Pacific ports in 1897. From Dyea, travelers climbed the steep Chilkoot Trail; from Skagway, they attempted the longer White Pass route. Both converged near the headwaters of the Yukon River for the journey to Dawson.</p><p>Canadian authorities required entrants to carry roughly a year’s supplies—commonly remembered as a “ton of goods.” Moving that load created work for Tlingit packers and later for tramways, pack animals, and freight companies. It also produced suffering: avalanches, exposure, disease, overloaded animals, fraud, and violence.</p><p>Skagway and Dyea boomed as supply towns. Dyea rapidly declined; Skagway endured after the White Pass &amp; Yukon Route railway reached Whitehorse in 1900. Alaska’s chief Klondike profit was therefore not mined gold but transportation, outfitting, construction, and trade.</p><p className="source-note">Sources <a href="#source-5">5</a>, <a href="#source-6">6</a>, and <a href="#source-7">7</a>.</p></div>
                                </article>
                                <article className="timeline-card" data-era="far-north">
                                    <div className="timeline-card__date">1898–1900</div>
                                    <div><p className="eyebrow">Seward Peninsula · Iñupiat homeland</p><h3>Nome puts gold on the beach</h3><p>After discoveries near Anvil Creek in 1898, miners found gold-bearing sands on the beach at Nome in 1899. Because the beach could initially be worked without conventional creek claims, newcomers arrived by sea in extraordinary numbers during 1900. Tents, businesses, courts, and municipal government appeared almost at once.</p><p>Nome’s accessibility changed the economics of a rush: ocean steamers could land people close to the diggings, avoiding the mountain trails that defined the Klondike. Yet the new city also occupied Iñupiat homeland and brought disease, pressure on subsistence resources, racial exclusion, claim disputes, and lasting disturbance from dredging.</p><p className="source-note">Sources <a href="#source-8">8</a> and <a href="#source-9">9</a>.</p></div>
                                </article>
                                <article className="timeline-card" data-era="far-north">
                                    <div className="timeline-card__date">1902–06</div>
                                    <div><p className="eyebrow">Tanana Valley · Interior</p><h3>Fairbanks turns a camp into a regional center</h3><p>Trader E. T. Barnette established a post on the Chena River in 1901. Felix Pedro’s 1902 discovery nearby brought prospectors and supplied the settlement that became Fairbanks. As shallow placer deposits were exhausted, larger dredges and engineered water systems favored companies with machinery and capital.</p><p>Government followed commerce. Courts, roads, mail, and telegraph links expanded across a territory where travel was difficult and federal authority thin. Alaska gold production peaked in 1906 at more than one million troy ounces, reflecting the shift from individual panning to industrial extraction.</p><p className="source-note">Sources <a href="#source-10">10</a> and <a href="#source-11">11</a>.</p></div>
                                </article>
                            </div>
                        </div>
                    </section>

                    <section className="section" id="consequences">
                        <div className="container article-grid">
                            <div className="section-label">03 · What remained</div>
                            <article>
                                <h2>The rush ended. Its systems did not.</h2>
                                <div className="impact-grid">
                                    <section><h3>People</h3><p>Rush populations were diverse, but opportunity was unequal. Native people supplied knowledge, food, transport, and labor while facing dispossession and disruption. Women ran hotels, laundries, restaurants, newspapers, and claims. Black, Chinese, Japanese, Scandinavian, and other migrants encountered both opportunity and legal or social exclusion.</p></section>
                                    <section><h3>Infrastructure</h3><p>Ports, rail, roads, riverboats, telegraph lines, and supply chains connected Alaska more tightly to Seattle and the continental United States. Juneau, Nome, Fairbanks, and Skagway outlasted the first frenzy because they became administrative or transport centers.</p></section>
                                    <section><h3>Environment</h3><p>Hydraulic methods, shafts, tailings, and later dredges rearranged streams and wetlands. Mercury used to recover fine gold left contamination at some sites. Today, preserved trails and buildings coexist with abandoned workings and continuing remediation.</p></section>
                                    <section><h3>Memory</h3><p>The lone prospector remains the dominant image, but gold rushes were collective systems: Indigenous routes, global migration, corporate capital, public law, food, transport, and labor. Reading them together produces a less romantic—and more useful—history.</p></section>
                                </div>
                            </article>
                        </div>
                    </section>

                    <section className="section section--sources" id="sources">
                        <div className="container article-grid">
                            <div className="section-label">04 · Sources</div>
                            <article>
                                <h2>Read beyond the summary</h2>
                                <p>This interpretive demo favors public institutions and links directly to the material used. Historical language and estimates vary by source.</p>
                                <ol className="sources-list">
                                    {sources.map(([id, label, href]) => <li id={id}><a href={href}>{label}</a></li>)}
                                </ol>
                            </article>
                        </div>
                    </section>
                </main>
                <footer className="site-footer"><div className="container"><p>Gold North is a demonstration of the white-label TypeScript web stack.</p><a href="#top">Back to top ↑</a></div></footer>
                <script src={`${page.cdn}release/${page.version}/assets/script/index.compiled.js`} defer />
            </body>
        </html>
    );
}
